// ===== Employer-Scout: Parameter (nur hier ändern) =====
const MODEL = 'gemini-3.1-flash-lite';   // Modell an EINER Stelle; Ersatz: FALLBACK_MODEL
const FALLBACK_MODEL = 'gemini-3.8-flash'; // Ersatz, wenn das Hauptmodell nach 3 Versuchen ausfällt (z. B. 503 high demand)
const RESULTS = 10;                 // erster Test: 10, danach 20
const KEYWORD_INDEX = 0;            // 0 = automatisch nach Kalenderwoche (für den Zeitplan), 1-17 = festes Stichwort für Tests (Nummer siehe KEYWORDS)
const TEMPERATURE = 0;              // falls Gemini sich wiederholt oder abbricht: 1 versuchen
const GROUNDING = false;            // Google-Suche in Gemini: erst testen, ob der Free Tier das erlaubt
const MAX_WISHLIST = 300;           // Budget für die Wunschliste (Airtable Free: 1.000 Datensätze pro Base)
const MAX_KM = 7;                   // Hybrid/Vor Ort: max. Luftlinie von zu Hause
const HOME = { lat: 0, lon: 0 };  // REFERENCE_POINT: Koordinaten deines Bezugspunkts eintragen
const SIZE_MIN = 20, SIZE_MAX = 50000;

// c = Cluster, k = Stichwort (Reihenfolge = Wochenwechsel; Cluster abwechselnd)
const KEYWORDS = [
  { c: 'Automatisierung',  k: 'Prozessautomatisierung / Workflow-Automatisierung (n8n, Make, Zapier)' },
  { c: 'Projektassistenz', k: 'Projektassistenz / Projektassistent/in / Assistenz Projektmanagement / Projektorganisation' },
  { c: 'Controlling',      k: 'Projektcontrolling / Projektsteuerung / Kaufmännische Projektsteuerung (Projektkaufmann)' },
  { c: 'Operations',       k: 'Operations Specialist / Operations Manager / Business Operations' },
  { c: 'Automatisierung',  k: 'KI-Agenten / KI-Integration in Geschäftsprozesse' },
  { c: 'Projektassistenz', k: 'Projektkoordination / Project Coordinator / PMO (Projektmanagement Office)' },
  { c: 'Controlling',      k: 'Controlling / Junior Controller / Soll-Ist-Vergleich / Budgetplanung' },
  { c: 'Operations',       k: 'Prozessmanagement / Prozessmanager / Business Process Management / Continuous Improvement' },
  { c: 'Automatisierung',  k: 'Geschäftsprozessmanagement / BPMN / Prozessoptimierung' },
  { c: 'Projektassistenz', k: 'Unit-Assistenz / Rechnungsbearbeitung / Zeiterfassung' },
  { c: 'Controlling',      k: 'Kostensteuerung / Kostenkontrolle / Terminsteuerung / Projektabrechnung / Leistungsnachweise' },
  { c: 'Operations',       k: 'Business Analyse' },
  { c: 'Automatisierung',  k: 'Low-Code / No-Code / Citizen Development' },
  { c: 'Controlling',      k: 'Reporting / Berichtswesen / Vertragsmanagement / Excel (Pivot)' },
  { c: 'Automatisierung',  k: 'Wissensmanagement / interne KI-Tools' },
  { c: 'Automatisierung',  k: 'Datenschutz / DSGVO / AI Act / KI-Governance' },
  { c: 'Automatisierung',  k: 'Digitalisierung von Geschäftsprozessen' },
];

// Negative Stichwörter: Firmen, deren Stellen in diesem Feld hauptsächlich darum gehen, sollen nicht vorgeschlagen werden
const NEGATIVE = ['Empfang', 'Rezeption', 'Kasse', 'Fraud', 'KYC', 'Payroll', 'Store', 'Büromanagement', 'Assistenz der Geschäftsführung', 'Sekretariat'];

let idx = KEYWORD_INDEX;
if (!idx) {
  const d = new Date();
  const start = new Date(d.getFullYear(), 0, 1);
  const week = Math.ceil(((d - start) / 86400000 + start.getDay() + 1) / 7);
  idx = (week % KEYWORDS.length) + 1;
}
if (idx < 1 || idx > KEYWORDS.length) throw new Error('KEYWORD_INDEX muss 0 bis ' + KEYWORDS.length + ' sein.');

return [{ json: {
  model: MODEL, fallback_model: FALLBACK_MODEL, results: RESULTS, keyword_index: idx, keyword: KEYWORDS[idx - 1].k, keyword_cluster: KEYWORDS[idx - 1].c, negative: NEGATIVE.join(', '),
  temperature: TEMPERATURE, grounding: GROUNDING, max_wishlist: MAX_WISHLIST,
  max_km: MAX_KM, home: HOME, size_min: SIZE_MIN, size_max: SIZE_MAX,
} }];

// Baut den EINEN Gemini-Aufruf. Keine persönlichen Daten im Prompt.
const p = $('Parameter').first().json;
const NAME = 'Name des Arbeitgebers';

const existing = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const n = (j.fields && j.fields[NAME]) || j[NAME];
  if (n) existing.push(String(n).trim());
}

const free = p.max_wishlist - existing.length;
if (free <= 0) throw new Error(`Wunschliste hat ${existing.length} Einträge (Grenze ${p.max_wishlist}). Erst aufräumen, dann neu starten.`);
const n = Math.min(p.results, free);

const prompt = `You are a research assistant building a list of potential employers in Berlin, Germany.

Task: list up to ${n} real companies that
- have an office in Berlin,
- have between ${p.size_min} and ${p.size_max} employees,
- are likely to employ people in this field: "${p.keyword}",
- may be in any industry.
Prefer companies whose Berlin office is within about ${p.max_km} km of Alexanderplatz, or that work fully remote.

Do NOT include these companies (already on the list): ${existing.length ? existing.join('; ') : 'none'}

Strict rules:
1. Only list companies you are certain exist and have an office in Berlin. If unsure, leave the company out. Fewer results are better than invented ones.
2. website_domain: the company's real main domain, without "https://" and without a path (example: "example.com"). Only if you know it. Never guess. If unknown, null.
3. careers_url: only a full URL you know exists. Never construct or guess a URL (for example by adding "/karriere" or "/jobs" to the domain). If unknown, null.
4. berlin_office_address: street, house number, postcode, "Berlin". Only if you know it. Never invent an address. If unknown, null.
5. work_mode_guess: "Remote", "Hybrid", "Vor Ort", or null if unknown.
6. industry: short German label (for example "Software", "E-Commerce", "Energie").
7. why_it_fits: one short German sentence on why the company fits the field "${p.keyword}". No invented facts.
8. Leave out companies whose openings in this field are mainly about: ${p.negative}.\n9. Return only JSON of the form {"employers": [...]}, no other text.`;

const schema = {
  type: 'OBJECT',
  properties: {
    employers: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          name: { type: 'STRING' },
          website_domain: { type: 'STRING', nullable: true },
          industry: { type: 'STRING', nullable: true },
          berlin_office_address: { type: 'STRING', nullable: true },
          work_mode_guess: { type: 'STRING', nullable: true, enum: ['Remote', 'Hybrid', 'Vor Ort'] },
          careers_url: { type: 'STRING', nullable: true },
          why_it_fits: { type: 'STRING', nullable: true },
        },
        required: ['name', 'website_domain', 'industry', 'berlin_office_address', 'work_mode_guess', 'careers_url', 'why_it_fits'],
      },
    },
  },
  required: ['employers'],
};

const body = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { temperature: p.temperature, maxOutputTokens: 16384 },
};
if (p.grounding) {
  body.tools = [{ google_search: {} }];          // mit Grounding kein Schema-Modus
} else {
  body.generationConfig.responseMimeType = 'application/json';
  body.generationConfig.responseSchema = schema;
}

return [{ json: { body, existing, requested: n } }];

// Gemini-Antwort lesen, säubern, Duplikate entfernen.
const r = $input.first().json;
const existing = $('Prompt bauen').first().json.existing || [];

if (r.error) throw new Error('Gemini-Fehler: ' + JSON.stringify(r.error).slice(0, 500));
const cand = (r.candidates || [])[0];
if (!cand) throw new Error('Gemini hat keine Antwort geliefert: ' + JSON.stringify(r).slice(0, 500));
const text = ((cand.content || {}).parts || []).map(x => x.text || '').join('').trim();

let data;
try {
  data = JSON.parse(text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, ''));
} catch (e) {
  throw new Error(`Antwort ist kein gültiges JSON (finishReason: ${cand.finishReason}). Anfang: ${text.slice(0, 300)}`);
}
const list = Array.isArray(data) ? data : (data.employers || []);

const LEGAL = /\b(gmbh|ag|se|kgaa|kg|ug|ohg|gbr|e\.?\s?v|b\.?\s?v|n\.?\s?v|s\.?\s?a\.?\s?r\.?\s?l|s\.?\s?r\.?\s?l|s\.?\s?p\.?\s?a|s\.?\s?a\.?\s?s|s\.?\s?a|mbh|co|inc|ltd|limited|llc|plc|corp|corporation|group|holding|oy|aps|haftungsbeschränkt)\b\.?/g;
const norm = s => String(s || '').toLowerCase()
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
  .replace(/&/g, ' ').replace(LEGAL, ' ').replace(/[^a-z0-9]+/g, '');
const cleanDomain = d => {
  if (!d) return null;
  const s = String(d).trim().toLowerCase().replace(/^https?:\/\//, '').split(/[\/?#]/)[0];
  return /^[a-z0-9.-]+\.[a-z]{2,}$/.test(s) ? s : null;
};
const cleanUrl = u => (u && /^https?:\/\/[^\s]+\.[^\s]+/i.test(String(u).trim())) ? String(u).trim() : null;
const clean = v => (v === null || v === undefined || String(v).trim() === '' || String(v).toLowerCase() === 'null') ? null : String(v).trim();

const seen = new Set(existing.map(norm));
const duplicates = [];
const out = [];
for (const e of list) {
  const name = clean(e && e.name);
  if (!name) continue;
  const key = norm(name);
  if (!key || seen.has(key)) { duplicates.push(name); continue; }
  seen.add(key);
  const mode = ['Remote', 'Hybrid', 'Vor Ort'].includes(e.work_mode_guess) ? e.work_mode_guess : null;
  out.push({ json: {
    name,
    website_domain: cleanDomain(e.website_domain),
    industry: clean(e.industry),
    berlin_office_address: clean(e.berlin_office_address),
    work_mode_guess: mode,
    careers_url: cleanUrl(e.careers_url),
    why_it_fits: clean(e.why_it_fits),
  } });
}

const meta = { found: list.length, duplicates, finishReason: cand.finishReason || null, usage: r.usageMetadata || null, model: r.modelVersion || null };
if (!out.length) throw new Error(`Keine neuen Firmen (gefunden: ${list.length}, Duplikate: ${duplicates.length}). Anderes Stichwort in "Parameter" wählen.`);
out[0].json._meta = meta;
return out;

// Anti-Halluzinations-Prüfung V1-V3 + Adresse aus Impressum (deterministisch, ohne KI). v1.3
// v1.3: Adresse wird aus Impressum/Startseite gelesen; Gemini-Adresse nur als Ersatz.
// v1.2: ausländische Rechtsformen (B.V., S.A., ...); Karriereseite mit Bot-Schutz akzeptiert; Grund im Hinweis.
// Änderungen v1.1:
// - HTML wird aus "data" ODER "body" gelesen (n8n legt Text-Antworten in "data" ab).
// - Bot-Schutz (401/403/406/429/503/999, Timeout, Verbindungsabbruch) zählt als "Server existiert".
//   Dann gilt V3 als bestanden, wenn der Domainname zum Firmennamen passt (Hinweis im Datensatz).
// - DNS-Fehler (Domain existiert nicht) = abgelehnt.
const orig = $('Antwort parsen').all();
const web = $('Website prüfen').all();
const car = $('Karriereseite prüfen').all();

const ATS = ['personio', 'join.com', 'greenhouse', 'lever.co', 'smartrecruiters', 'workday', 'softgarden',
             'recruitee', 'stepstone', 'ashbyhq', 'teamtailor', 'workable'];
const BLOCKED = [401, 403, 406, 429, 503, 999];
const DNS_FAIL = /ENOTFOUND|EAI_AGAIN|getaddrinfo|NXDOMAIN|not resolve|invalid\.invalid|Invalid URL|ERR_INVALID_URL/i;
const GENERIC = /\b(ventures|venture|technologies|technology|tech|labs|lab|solutions|services|digital|software|systems|consulting|deutschland|germany|berlin|international|europe)\b/g;
const LEGAL = /\b(gmbh|ag|se|kgaa|kg|ug|ohg|gbr|e\.?\s?v|b\.?\s?v|n\.?\s?v|s\.?\s?a\.?\s?r\.?\s?l|s\.?\s?r\.?\s?l|s\.?\s?p\.?\s?a|s\.?\s?a\.?\s?s|s\.?\s?a|mbh|co|inc|ltd|limited|llc|plc|corp|corporation|group|holding|oy|aps)\b\.?/g;

const errText = it => {
  if (!it) return 'keine Antwort';
  const e = (it.json && it.json.error) || it.error;
  if (!e) return '';
  return typeof e === 'string' ? e : JSON.stringify(e);
};
const status = it => (it && it.json && !errText(it) && it.json.statusCode) ? it.json.statusCode : null;
const html = it => {
  const j = (it && it.json) || {};
  const v = typeof j.data === 'string' ? j.data : (typeof j.body === 'string' ? j.body : '');
  return v;
};
// Ergebnis einer Abfrage: ok (200) | blocked (Server da, aber gesperrt) | dns (Domain gibt es nicht) | fail
const classify = it => {
  const s = status(it);
  if (s === 200) return { kind: 'ok', code: 200 };
  if (s && BLOCKED.includes(s)) return { kind: 'blocked', code: s };
  if (s) return { kind: 'fail', code: s };
  const t = errText(it);
  if (DNS_FAIL.test(t)) return { kind: 'dns', code: 'Domain existiert nicht' };
  const m = t.match(/\bE[A-Z]{4,}\b/) || t.match(/timeout/i);
  return { kind: 'blocked', code: 'keine Antwort' + (m ? ' (' + m[0] + ')' : '') };
};
const decode = s => s.toLowerCase()
  .replace(/&amp;/g, '&').replace(/&auml;/g, 'ä').replace(/&ouml;/g, 'ö').replace(/&uuml;/g, 'ü').replace(/&szlig;/g, 'ß')
  .replace(/&#x?[0-9a-f]+;/g, ' ');
const compact = s => s.replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '');
const hostOf = u => { const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
// Domain passt zum Namen: zalando.de <-> Zalando, deliveryhero.com <-> Delivery Hero, project-a.vc <-> Project A Ventures
const domainMatches = (domain, core) => {
  const parts = (domain || '').replace(/^www\./, '').split('.');
  if (parts.length < 2) return false;
  const label = compact(parts.slice(0, -1).join(''));
  const c = compact(core);
  if (label.length < 4 || c.length < 4) return false;
  return label.includes(c) || c.includes(label);
};

// --- Adresse aus Impressum ---
const toText = h => String(h || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|span|address|td|h\d)>/gi, ', ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ').replace(/&middot;|&#183;|&bull;/gi, '·').replace(/&amp;/gi, '&').replace(/&szlig;/gi, 'ß')
  .replace(/&auml;/gi, 'ä').replace(/&ouml;/gi, 'ö').replace(/&uuml;/gi, 'ü')
  .replace(/&Auml;/g, 'Ä').replace(/&Ouml;/g, 'Ö').replace(/&Uuml;/g, 'Ü')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n))
  .replace(/\\u00df/g, 'ß').replace(/\\u00e4/g, 'ä').replace(/\\u00f6/g, 'ö').replace(/\\u00fc/g, 'ü')
  .replace(/[\s ]+/g, ' ');
const W = "[A-ZÄÖÜ][A-Za-zäöüßÄÖÜé\\-]*";
const SUF = "(?:[Ss]tra(?:ß|ss)e|[Ss]tr\\.|[Pp]latz|[Aa]llee|[Dd]amm|[Uu]fer|[Ww]eg|[Rr]ing|[Mm]arkt|[Cc]haussee|[Gg]asse|[Pp]romenade|[Bb]rücke|[Ss]teig|[Gg]raben|[Kk]ai|[Zz]eile|[Pp]ark|[Hh]of|[Tt]or|[Bb]ogen)";
const NOTWORD = "(?!(?:GmbH|AG|SE|KG|Co|mbH|Inc|Ltd|Anschrift|Adresse|Address|Sitz|Berlin|Germany|Deutschland|Postanschrift|Hausanschrift|Office|Registered)\\b)";
const ADDR = new RegExp(
  "(?<![\\wäöüßÄÖÜ\\-])(" + "(?:" + NOTWORD + W + "\\s)?" + "(?:" + W + SUF + "|" + SUF + ")" + ")" +
  "\\.?\\s*(\\d{1,4}\\s?[a-zA-Z]?(?:\\s?[-–\\/]\\s?\\d{1,4}[a-zA-Z]?)?)" +
  "\\s*[,|·•]?\\s*(?:D-|DE-)?(1[0-4]\\d{3}),?\\s+Berlin", "g");
const findAddress = html => {
  const t = toText(html);
  const out = [];
  for (const m of t.matchAll(ADDR)) out.push(`${m[1].trim()} ${m[2].replace(/\s+/g, '')}, ${m[3]} Berlin`);
  return out;
};


const impUrls = (() => { try { return $('Impressum-URLs').all(); } catch (e) { return []; } })();
const impRes = (() => { try { return $('Impressum laden').all(); } catch (e) { return []; } })();
const imp = impUrls.map((u, k) => ({ idx: u.json.idx, ok: status(impRes[k]) === 200, html: html(impRes[k]) }));

const accepted = [];
const rejected = [];
for (let i = 0; i < orig.length; i++) {
  const e = orig[i].json;
  const reasons = [];
  const warnings = [];
  const core = e.name.toLowerCase().replace(LEGAL, ' ').replace(/\s+/g, ' ').trim() || e.name.toLowerCase();
  // Kurzform ohne Zusätze wie "Ventures", "Technologies" (Project A Ventures -> project a)
  const shortCore = core.replace(GENERIC, ' ').replace(/\s+/g, ' ').trim();
  // "Babbel (Lesson Nine GmbH)": Teil vor und in der Klammer separat prüfen
  const outer = core.replace(/\(.*?\)/g, ' ').replace(/\s+/g, ' ').trim();
  const inner = ((core.match(/\((.*?)\)/) || [])[1] || '').replace(LEGAL, ' ').replace(/\s+/g, ' ').trim();
  const names = [core, shortCore, outer, inner].filter((n, k, a) => n && compact(n).length >= 4 && a.indexOf(n) === k);

  // V1: Website existiert
  const w = e.website_domain ? classify(web[i]) : { kind: 'dns', code: 'keine Website angegeben' };
  const v1 = w.kind === 'ok' || w.kind === 'blocked';
  if (!e.website_domain) reasons.push('keine Website angegeben');
  else if (!v1) reasons.push(`Website ${e.website_domain}: ${w.code}`);

  // V2: Karriereseite (200 + eigene Domain oder bekanntes ATS)
  const c = e.careers_url ? classify(car[i]) : { kind: 'fail', code: null };
  const cHost = hostOf(e.careers_url || '');
  const root = (e.website_domain || '').replace(/^www\./, '');
  const hostOk = !!cHost && ((root && (cHost === root || cHost.endsWith('.' + root))) || ATS.some(a => cHost.includes(a)));
  const v2 = !!e.careers_url && hostOk && (c.kind === 'ok' || c.kind === 'blocked');
  if (!e.careers_url) warnings.push('Karriereseite nicht gefunden (keine URL von Gemini)');
  else if (!hostOk) warnings.push(`Karriereseite nicht gefunden (fremde Domain: ${cHost || 'ungültig'})`);
  else if (!v2) warnings.push(`Karriereseite nicht gefunden (${c.code})`);
  else if (c.kind === 'blocked') warnings.push(`Karriereseite blockiert Prüfung (${c.code})`);

  // V3: Firmenname auf Website/Karriereseite; bei Bot-Schutz: Domain passt zum Namen
  const webHtml = w.kind === 'ok' ? html(web[i]) : '';
  const pages = [webHtml, (v2 && c.kind === 'ok') ? html(car[i]) : ''].map(decode);
  const nameOnPage = pages.some(h => h && (h.includes(core) || names.some(n => compact(h).includes(compact(n)))));
  let v3 = nameOnPage;
  if (v1 && !v3 && w.kind === 'blocked' && domainMatches(e.website_domain, core)) {
    v3 = true;
    warnings.push(`Website blockiert automatische Prüfung (${w.code}), Name nur über Domain geprüft`);
  }
  if (v1 && !v3) {
    reasons.push(w.kind === 'blocked'
      ? `Website blockiert Prüfung (${w.code}) und Domain passt nicht zum Namen`
      : `Firmenname nicht auf der Website gefunden (HTML: ${webHtml.length} Zeichen)`);
  }

  // Adresse: zuerst Impressum-Seiten, dann Startseite
  let imprint_address = null;
  for (const h of [...imp.filter(x => x.idx === i && x.ok).map(x => x.html), webHtml]) {
    const a = h ? findAddress(h) : [];
    if (a.length) { imprint_address = a[0]; break; }
  }

  if (v1 && v3) accepted.push({ json: { ...e, _meta: undefined, v2_ok: v2, domain_only: w.kind === 'blocked', imprint_address, warnings } });
  else rejected.push({ name: e.name, grund: reasons.join('; ') });
}

if (!accepted.length) return [{ json: { nothing: true, _rejected: rejected, _total: orig.length } }];
for (const a of accepted) { a.json._rejected = rejected; a.json._total = orig.length; }
return accepted;

// Entfernung von zu Hause (Luftlinie) + Airtable-Datensätze vorbereiten.
const p = $('Parameter').first().json;
const items = $('Prüfen').all();
const geo = $input.all();
const HOME = p.home;
const modelUsed = (($('Antwort parsen').first().json._meta || {}).model) || p.model;
const today = $now.toFormat('yyyy-MM-dd');

const rad = x => x * Math.PI / 180;
const haversine = (a, b) => {
  const dLat = rad(b.lat - a.lat), dLon = rad(b.lon - a.lon);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(h));
};

const records = [];
const tooFar = [];
const noAddress = [];
const noCareers = [];
const domainOnly = [];
const fromImprint = [];
const geminiWrong = [];
const comp = s => String(s || '').toLowerCase().replace(/straße|strasse/g, 'str').replace(/[^a-z0-9äöü]/g, '');
const same = (a, b) => { const pa = (a.match(/\b1[0-4]\d{3}\b/) || [])[0], pb = (b.match(/\b1[0-4]\d{3}\b/) || [])[0]; return pa === pb && comp(a).slice(0, 8) === comp(b).slice(0, 8); };

for (let i = 0; i < items.length; i++) {
  const e = items[i].json;
  if (e.nothing) continue;

  const addr = e.imprint_address || e.berlin_office_address;
  const src = e.imprint_address ? 'Adresse laut Impressum' : 'Adresse von Gemini, nicht verifiziert';
  let km = null;
  if (addr) {
    let arr = null;
    const g = geo[i] && geo[i].json ? (typeof geo[i].json.data === 'string' ? geo[i].json.data : geo[i].json.body) : null;
    try { arr = typeof g === 'string' ? JSON.parse(g) : g; } catch (err) { arr = null; }
    if (Array.isArray(arr) && arr[0] && arr[0].lat) {
      km = Math.round(haversine(HOME, { lat: +arr[0].lat, lon: +arr[0].lon }) * 10) / 10;
    }
  }
  const warnings = [...(e.warnings || [])];
  if (km === null) { warnings.push('Adresse nicht geprüft'); noAddress.push(e.name); }

  // Entfernungsregel gilt für alles außer "Remote" (auch für unbekannten Arbeitsmodus)
  if (e.work_mode_guess !== 'Remote' && km !== null && km > p.max_km) {
    tooFar.push({ name: e.name, km, modus: e.work_mode_guess || 'unbekannt' });
    continue;
  }

  if (!e.v2_ok) noCareers.push(e.name);
  if (e.domain_only) domainOnly.push(e.name);
  let geminiNote = null;
  if (e.imprint_address) {
    fromImprint.push(e.name);
    if (e.berlin_office_address && !same(e.imprint_address, e.berlin_office_address)) { geminiWrong.push(e.name); geminiNote = `Gemini hatte ${e.berlin_office_address} angegeben (abweichend).`; }
  } else if (!e.domain_only) warnings.push('keine Berliner Adresse im Impressum gefunden');

  const notes = [
    `Fokus (${p.keyword_cluster}): ${p.keyword}`,
    e.why_it_fits || null,
    km !== null ? `Entfernung von zu Hause: ${String(km).replace('.', ',')} km (Luftlinie, ${src})` : null,
    geminiNote,
    e.work_mode_guess ? null : 'Arbeitsmodus unbekannt',
    warnings.length ? 'Hinweise: ' + [...new Set(warnings)].join(', ') : null,
    `Employer-Scout ${today}, Modell ${modelUsed}`,
  ].filter(Boolean).join('\n');

  const fields = {
    fldsF7QizI7J65GrS: e.name,                                  // Name des Arbeitgebers
    fldAalhTRAmssY96o: addr || 'Berlin',                         // Standort (Impressum vor Gemini)
    fldO6QeTNdkt370U7: e.industry,                              // Branche
    fldRlJZxADTfcbTTz: e.work_mode_guess,                       // Arbeitsort
    fldpC1zthl85U3itZ: 'Neu (vom Scout vorgeschlagen)',         // Status
    fldCnPYVpHbAe9lPI: 'KI-Prompt',                             // Quelle
    flde03QfdDq2KIXkT: 'Unbekannt',                             // KI-Bezug
    fldFIaM38DVcUUTRA: today,                                   // Zuletzt geprüft
    fldv3Q0ZQ9zo5NS1I: notes,                                   // Notizen
    fldLrD0XwVXbE8uMU: e.v2_ok ? e.careers_url : null,          // Link zur Karriereseite
  };
  for (const k of Object.keys(fields)) if (fields[k] === null || fields[k] === undefined) delete fields[k];
  records.push({ fields });
}

const summary = { tooFar, noAddress, noCareers, domainOnly, fromImprint, geminiWrong };
const out = [];
for (let i = 0; i < records.length; i += 10) out.push({ json: { records: records.slice(i, i + 10), _summary: summary } });
if (!out.length) out.push({ json: { records: [], _summary: summary } });
return out;

// Zusammenfassung des Laufs.
const p = $('Parameter').first().json;
const meta = $('Antwort parsen').first().json._meta || {};
const checked = $('Antwort parsen').all().length;
const chk = $('Prüfen').first().json;
const rejected = chk._rejected || [];
const s = $('Entfernung').first().json._summary || {};

const added = [];
const errors = [];
let fb = false;
try { fb = $('Gemini Ersatz').isExecuted; } catch (e) { fb = false; }
let wrote = false;
try { wrote = $('In Airtable speichern').isExecuted; } catch (e) { wrote = false; }
if (wrote) {
  for (const it of $('In Airtable speichern').all()) {
    if (it.json.error) { errors.push(JSON.stringify(it.json.error).slice(0, 300)); continue; }
    for (const r of it.json.records || []) {
      const f = r.fields || {};
      added.push(f['Name des Arbeitgebers'] || f.fldsF7QizI7J65GrS || r.id);
    }
  }
}

const rate = checked ? Math.round(rejected.length / checked * 100) : 0;
return [{ json: {
  'Modell': meta.model || p.model,
  'Ersatzmodell genutzt': fb ? p.fallback_model : null,
  'Fokus': `${p.keyword_index}: [${p.keyword_cluster}] ${p.keyword}`,
  'Gemini-Aufrufe': 1,
  'Gemini-Tokens': meta.usage ? meta.usage.totalTokenCount : null,
  'Von Gemini gefunden': meta.found,
  'Duplikate übersprungen': meta.duplicates || [],
  'Hinzugefügt': added,
  'Abgelehnt (evtl. erfunden)': rejected,
  ['Zu weit (> ' + p.max_km + ' km)']: s.tooFar || [],
  'Karriereseite nicht gefunden': s.noCareers || [],
  'Nur über Domain geprüft (Bot-Schutz)': s.domainOnly || [],
  'Adresse aus Impressum': s.fromImprint || [],
  'Gemini-Adresse falsch': s.geminiWrong || [],
  'Adresse nicht geprüft': s.noAddress || [],
  'Speicherfehler': errors,
  'Ablehnungsquote': rate + ' %',
  'Warnung': rate > 30 ? 'Mehr als 30 % abgelehnt: Prompt oder Stichwort anpassen.' : null,
  'Gemini-Abbruchgrund': meta.finishReason,
} }];

// Impressum-Seiten pro Firma bestimmen (ohne KI). v1.3
// 1. Link mit "impressum"/"imprint" von der Startseite, 2. übliche Pfade.
const orig = $('Antwort parsen').all();
const web = $('Website prüfen').all();
const PATHS = ['/impressum', '/imprint', '/de/impressum', '/legal'];
const html = it => {
  const j = (it && it.json) || {};
  return typeof j.data === 'string' ? j.data : (typeof j.body === 'string' ? j.body : '');
};

// n8n-Sandbox kennt kein URL-Objekt: eigene Hilfsfunktion
const absUrl = (href, domain) => /^https?:\/\//i.test(href) ? href : href.startsWith('//') ? 'https:' + href : 'https://' + domain + (href.startsWith('/') ? '' : '/') + href;

const out = [];
for (let i = 0; i < orig.length; i++) {
  const d = orig[i].json.website_domain;
  if (!d) continue;
  const urls = [];
  const m = html(web[i]).match(/href=["']([^"'#\s]*?(?:impressum|imprint)[^"'#\s]*)["']/i);
  if (m) urls.push(absUrl(m[1].replace(/&amp;/g, '&'), d));
  for (const p of PATHS) urls.push('https://' + d + p);
  for (const u of [...new Set(urls)]) out.push({ json: { idx: i, url: u } });
}
if (!out.length) out.push({ json: { idx: -1, url: 'https://invalid.invalid' } });
return out;
